#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# feedr deployment setup: the accounts and dashboards only you can reach. It protects main,
# sets up Railway (Postgres and the API), lets the TestFlight app sign in through Clerk, links
# the Expo project, sets up Apple signing and the App Store Connect app, gives GitHub what the
# release and backup workflows need, then makes the first TestFlight build.
# Run it from the repo root: ./scripts/deploy-setup.sh. Safe to re-run: finished stages are
# detected and skipped. Values that aren't secret are kept in .env.deploy (gitignored).

run_wizard() {

TOTAL_STAGES=14

cd "$(dirname "$0")/.."
ENV_FILE=.env.deploy
LOCAL_ENV=.env
MOBILE_ENV=apps/mobile/.env.local
APP_JSON=apps/mobile/app.json
EAS_JSON=apps/mobile/eas.json
BUNDLE_ID=$(jq -r .expo.ios.bundleIdentifier "$APP_JSON")
CHECKS='["Format, lint, typecheck, unit tests","API, migrations and image","App bundles for iOS"]'
BACKUP_KEY="$HOME/.config/feedr/backup-key.txt"

# ── Helpers for clear stage screens (as in scripts/setup.sh) ──────────────
what() { printf '  %sWhat this does:%s %s\n' "$BOLD" "$RESET" "$1"; }
you()  { printf '  %sYour part:%s %s\n\n' "$BOLD" "$RESET" "$1"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
cmd()  { printf '\n      %s%s%s\n\n' "$BOLD" "$1" "$RESET"; }
die()  { printf '\n'; warn "$1"; printf '\n'; exit 1; }

# Node and pnpm from mise.toml when mise is installed.
RUN=()
command -v mise >/dev/null 2>&1 && RUN=(mise exec --)
run() { ${RUN[@]+"${RUN[@]}"} "$@"; }
eas_cli() { (cd apps/mobile && run npx --yes eas-cli@latest "$@"); }
clerk_cli() {
  if command clerk --version >/dev/null 2>&1; then command clerk "$@"
  else run npx --yes clerk@2 "$@"; fi
}
# copy VALUE puts a value on the clipboard, so you paste it without it being shown.
copy() {
  if command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}
healthy() { [[ -n "${1:-}" ]] && curl -fsS --max-time 5 "$1/health" >/dev/null 2>&1; }
pretty() { run pnpm exec prettier --write "$@" >/dev/null; }

banner "feedr deployment setup"

# ── 1. Tools ───────────────────────────────────────────────────────────────
stage "Tools"
what "checks for the tools this wizard uses."
you "nothing, unless something is missing (it says what to install)."
[[ -f "$EAS_JSON" ]] || die "Run this from the branch with apps/mobile/eas.json (the deploy PR, or main once it's merged)."
command -v jq >/dev/null 2>&1 || die "jq is needed. Install it, then re-run."
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || die "The GitHub CLI must be signed in: gh auth login"
command -v age-keygen >/dev/null 2>&1 || die "age is needed for encrypted backups: sudo pacman -S age (or brew install age)."
[[ -f "$LOCAL_ENV" && -f "$MOBILE_ENV" ]] || die "Run ./scripts/setup.sh first: it creates the Clerk app this uses."
run pnpm --version >/dev/null 2>&1 || die "pnpm isn't available. Run ./scripts/setup.sh, which sets up mise."
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
ok "jq, gh (signed in), age, pnpm"
ok "Repository $REPO"
printf '\n'; pause

# ── 2. Protect main ────────────────────────────────────────────────────────
stage "Protect main"
what "adds a rule to GitHub so main only changes through a pull request whose"
say  "                CI checks pass and that is up to date with main. Railway deploys"
say  "                every commit on main, so this keeps broken code from deploying."
ruleset=$(gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "main") | .id' 2>/dev/null || true)
if [[ -n "$ruleset" ]]; then
  you "nothing."
  ok "main is protected (ruleset $ruleset)"
else
  you "say yes to add it."
  if confirm "Protect main with required CI checks?"; then
    jq -n --argjson checks "$CHECKS" '{
      name: "main", target: "branch", enforcement: "active",
      conditions: { ref_name: { include: ["~DEFAULT_BRANCH"], exclude: [] } },
      rules: [
        { type: "deletion" },
        { type: "non_fast_forward" },
        { type: "pull_request", parameters: {
            required_approving_review_count: 0, dismiss_stale_reviews_on_push: false,
            require_code_owner_review: false, require_last_push_approval: false,
            required_review_thread_resolution: false } },
        { type: "required_status_checks", parameters: {
            strict_required_status_checks_policy: true,
            required_status_checks: [$checks[] | { context: . }] } }
      ] }' | gh api "repos/$REPO/rulesets" -X POST --input - >/dev/null
    ok "main now needs a pull request with passing checks"
  else
    SKIPPED+=("Protect main: GitHub → Settings → Rules → Rulesets")
  fi
fi
printf '\n'; pause

# ── 3. Railway: project and Postgres ───────────────────────────────────────
FEEDR_API_URL=$(_existing FEEDR_API_URL || true)
stage "Railway: project and Postgres"
what "creates the Railway project with a Postgres database for feedr's data."
if healthy "$FEEDR_API_URL"; then
  you "nothing."
  ok "The API already answers at $FEEDR_API_URL"
else
  you "follow these steps in Railway (sign in with GitHub if asked)."
  open_url "https://railway.com/new"
  step "Create an empty project. Rename it feedr (project Settings)."
  step "Add a database: Create (or + New) → Database → PostgreSQL."
  step "Wait until the Postgres service shows as deployed."
  printf '\n'
  pause "Press Enter when Postgres is running."
fi
printf '\n'; pause

# ── 4. Railway: the API service ────────────────────────────────────────────
stage "Railway: the API service"
what "adds the API, built from this repo's Dockerfile, and sets when it deploys:"
say  "                only for commits on main that pass CI and touch the API."
if healthy "$FEEDR_API_URL"; then
  you "nothing."
  ok "The API is set up"
else
  you "follow these steps in the feedr project."
  step "Create (or + New) → GitHub Repo → $REPO. Allow Railway's GitHub app if asked."
  step "Rename the new service api. Railway finds the Dockerfile at the repo root."
  step "In the api service, open Settings, then set:"
  note "     Source → Branch: main, and turn on Wait for CI"
  note "     Build → Watch Paths, one per line:"
  note "       apps/api/**  packages/core/**  Dockerfile  package.json  pnpm-lock.yaml  pnpm-workspace.yaml"
  note "     Deploy → Healthcheck Path: /health"
  note "     Deploy → Restart Policy: On Failure"
  printf '\n'
  pause "Press Enter when those are saved."
fi
printf '\n'; pause

# ── 5. Railway: variables and address ──────────────────────────────────────
stage "Railway: variables and address"
what "gives the API its database and the Clerk key it checks sign-ins with,"
say  "                then a public https address for the app and your agents."
if healthy "$FEEDR_API_URL"; then
  you "nothing."
  ok "The API answers at $FEEDR_API_URL"
else
  you "follow these steps in the api service."
  step "Variables → New Variable: DATABASE_URL with the value \${{Postgres.DATABASE_URL}}"
  note "     (Railway turns that into the private address of the Postgres service.)"
  clerk_secret=$(ENV_FILE=$LOCAL_ENV _existing CLERK_SECRET_KEY || true)
  [[ -n "$clerk_secret" ]] || die "CLERK_SECRET_KEY isn't in $LOCAL_ENV. Run ./scripts/setup.sh first."
  if copy "$clerk_secret"; then
    step "Variables → New Variable: CLERK_SECRET_KEY, and paste. It's on your clipboard."
  else
    step "Variables → New Variable: CLERK_SECRET_KEY, with the value from $LOCAL_ENV."
  fi
  unset clerk_secret
  step "Deploy the changes when Railway offers to."
  step "Settings → Networking → Generate Domain. If it asks for a port, accept the one it suggests."
  printf '\n'
  while :; do
    ask FEEDR_API_URL "Paste the address (https://…up.railway.app):"
    FEEDR_API_URL=${FEEDR_API_URL%/}
    [[ "$FEEDR_API_URL" == https://* ]] || { warn "Use the https:// address."; continue; }
    write_env FEEDR_API_URL "$FEEDR_API_URL"
    printf '  Waiting for %s/health' "$FEEDR_API_URL"
    for _ in $(seq 1 60); do healthy "$FEEDR_API_URL" && break; printf '.'; sleep 5; done
    printf '\n'
    if healthy "$FEEDR_API_URL"; then ok "The API answers at $FEEDR_API_URL"; break; fi
    warn "No answer yet. Check the api service's Deployments tab: a build or a variable may be failing."
    confirm "Try again?" || { SKIPPED+=("Get the Railway API answering, then re-run"); break; }
  done
fi
printf '\n'; pause

# ── 6. Clerk: sign-in from the TestFlight app ──────────────────────────────
stage "Clerk: sign-in from the TestFlight app"
what "allows the installed app to receive the Apple or Google sign-in. Expo Go"
say  "                uses an exp:// address; the TestFlight app uses feedr://sso-callback."
you "nothing."
CLERK_APP_ID=$(ENV_FILE=$LOCAL_ENV _existing CLERK_APP_ID || true)
[[ -n "$CLERK_APP_ID" ]] || die "CLERK_APP_ID isn't in $LOCAL_ENV. Run ./scripts/setup.sh first."
redirect="feedr://sso-callback"
if clerk_cli api --app "$CLERK_APP_ID" /redirect_urls | jq -e --arg u "$redirect" 'any(.[]; .url == $u)' >/dev/null; then
  ok "Clerk allows $redirect"
else
  clerk_cli api --app "$CLERK_APP_ID" /redirect_urls --yes -d "{\"url\":\"$redirect\"}" >/dev/null
  ok "Allowed $redirect in Clerk"
fi
note "This uses the same Clerk development instance as local dev, so your sign-in works in both."
printf '\n'; pause

# ── 7. Expo: the project ───────────────────────────────────────────────────
stage "Expo: the project"
what "links the app to a project on your Expo account, which builds it and"
say  "                serves its over-the-air updates. This writes the project id into"
say  "                $APP_JSON; Claude commits it when you hand back."
project_id=$(jq -r '.expo.extra.eas.projectId // empty' "$APP_JSON")
if [[ -n "$project_id" ]]; then
  you "nothing."
  ok "Linked to Expo project $project_id"
else
  you "sign in to Expo if asked (sign up free at expo.dev if you have no account), then"
  say "           say yes to create the project."
  eas_cli whoami >/dev/null 2>&1 || eas_cli login
  eas_cli init
  project_id=$(jq -r '.expo.extra.eas.projectId // empty' "$APP_JSON")
  [[ -n "$project_id" ]] || die "eas init didn't write a projectId to $APP_JSON. Re-run this wizard."
  ok "Linked to Expo project $project_id"
fi
# Updates come from Expo's server for this project.
if [[ "$(jq -r '.expo.updates.url // empty' "$APP_JSON")" != "https://u.expo.dev/$project_id" ]]; then
  jq --arg u "https://u.expo.dev/$project_id" '.expo.updates.url = $u' "$APP_JSON" > "$APP_JSON.tmp" && mv "$APP_JSON.tmp" "$APP_JSON"
  pretty "$APP_JSON"
  ok "Set the update address in $APP_JSON"
fi
EXPO_ACCOUNT=$(jq -r '.expo.owner // empty' "$APP_JSON")
[[ -n "$EXPO_ACCOUNT" ]] || EXPO_ACCOUNT=$(eas_cli whoami 2>/dev/null | head -n1)
write_env EXPO_ACCOUNT "$EXPO_ACCOUNT"
printf '\n'; pause

# ── 8. Expo: the app's settings ────────────────────────────────────────────
stage "Expo: the app's settings"
what "stores the two values the app is built with in Expo's production"
say  "                environment: the API address and Clerk's publishable key. Both are"
say  "                public: they end up inside the app."
you "nothing."
clerk_pk=$(ENV_FILE=$MOBILE_ENV _existing EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY || true)
[[ -n "$clerk_pk" ]] || die "EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY isn't in $MOBILE_ENV. Run ./scripts/setup.sh first."
[[ -n "$FEEDR_API_URL" ]] || die "No API address yet. Finish the Railway stages first."
for pair in "EXPO_PUBLIC_API_URL=$FEEDR_API_URL" "EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY=$clerk_pk"; do
  name=${pair%%=*}; value=${pair#*=}
  eas_cli env:set --name "$name" --value "$value" --environment production \
    --visibility plaintext --non-interactive >/dev/null
  ok "$name is set for production builds and updates"
done
printf '\n'; pause

# ── 9. Apple: signing ──────────────────────────────────────────────────────
stage "Apple: signing"
what "registers the app's bundle id ($BUNDLE_ID) with Apple and creates the"
say  "                certificate, provisioning profile and App Store Connect API key that"
say  "                builds and TestFlight uploads use. Expo stores them, so CI can use them."
you "in the menu that opens, sign in with your Apple Developer account and:"
step "choose the production build profile,"
step "choose Build Credentials, then the option that sets up everything needed to build,"
step "then back in the menu choose App Store Connect, then set up an API Key for EAS Submit"
say  "           (let it generate a new key), then exit."
note "Re-running this is safe: it shows what's already set up."
printf '\n'
if confirm "Open Expo's credentials menu now?"; then eas_cli credentials --platform ios
else SKIPPED+=("Set up iOS credentials: cd apps/mobile && npx eas-cli@latest credentials --platform ios"); fi
printf '\n'; pause

# ── 10. App Store Connect: the app ─────────────────────────────────────────
stage "App Store Connect: the app"
what "creates feedr's record in App Store Connect, which TestFlight builds go"
say  "                to, and saves its Apple ID in $EAS_JSON so CI can submit."
asc_app_id=$(jq -r '.submit.production.ios.ascAppId // empty' "$EAS_JSON")
if [[ -n "$asc_app_id" ]]; then
  you "nothing."
  ok "App Store Connect app $asc_app_id"
else
  you "create the app in App Store Connect."
  open_url "https://appstoreconnect.apple.com/apps"
  step "Click + → New App. Platform: iOS."
  step "Name: anything unique on the App Store (\"feedr\" is probably taken). Testers see it."
  step "Bundle ID: $BUNDLE_ID (it's in the list after stage 9). SKU: feedr."
  step "Create, then open App Information. Copy the Apple ID (a number) under General Information."
  printf '\n'
  while :; do
    ask ASC_APP_ID "Paste the Apple ID:"
    [[ "$ASC_APP_ID" =~ ^[0-9]+$ ]] && break
    warn "That's not a number. It's the Apple ID under General Information, not the bundle id."
  done
  jq --arg id "$ASC_APP_ID" '.submit.production.ios.ascAppId = $id' "$EAS_JSON" > "$EAS_JSON.tmp" && mv "$EAS_JSON.tmp" "$EAS_JSON"
  pretty "$EAS_JSON"
  ok "Saved ascAppId $ASC_APP_ID in $EAS_JSON"
fi
printf '\n'; pause

# ── 11. GitHub: Expo token ─────────────────────────────────────────────────
stage "GitHub: Expo token"
what "lets the Release workflow build and update the app on your Expo account."
if gh secret list --repo "$REPO" --json name -q '.[].name' | grep -qx EXPO_TOKEN; then
  you "nothing."
  ok "GitHub has EXPO_TOKEN"
else
  you "create a token in Expo and paste it here (it's hidden as you paste)."
  open_url "https://expo.dev/accounts/$EXPO_ACCOUNT/settings/access-tokens"
  step "Create token. Name it github-actions. Copy it."
  ask_secret EXPO_TOKEN "Paste the token:"
  set_secret EXPO_TOKEN "$EXPO_TOKEN"
  unset EXPO_TOKEN
fi
printf '\n'; pause

# ── 12. Backups ────────────────────────────────────────────────────────────
stage "Backups"
what "sets up the nightly backup. Each dump is encrypted with a key that only"
say  "                lives on this machine, then kept in GitHub for 30 days."
if [[ -f "$BACKUP_KEY" ]]; then
  ok "Backup key at $BACKUP_KEY"
else
  mkdir -p "$(dirname "$BACKUP_KEY")"
  (umask 077 && age-keygen -o "$BACKUP_KEY" 2>/dev/null)
  ok "Made a backup key at $BACKUP_KEY"
  warn "Save a copy in your password manager. Without it the backups can't be read."
fi
set_var BACKUP_AGE_RECIPIENT "$(age-keygen -y "$BACKUP_KEY")"
if gh secret list --repo "$REPO" --json name -q '.[].name' | grep -qx DATABASE_PUBLIC_URL; then
  you "nothing."
  ok "GitHub has DATABASE_PUBLIC_URL"
else
  you "copy the database's public address from Railway (it's hidden as you paste)."
  step "In Railway, open the Postgres service → Variables → DATABASE_PUBLIC_URL, and copy it."
  note "     The backup runs on GitHub, outside Railway's private network, so it needs this one."
  ask_secret DATABASE_PUBLIC_URL "Paste DATABASE_PUBLIC_URL:"
  set_secret DATABASE_PUBLIC_URL "$DATABASE_PUBLIC_URL"
  unset DATABASE_PUBLIC_URL
fi
printf '\n'; pause

# ── 13. Hand back ──────────────────────────────────────────────────────────
stage "Hand back to Claude"
what "the setup that needs you is done. The first release has to come from"
say  "                main, so the deploy PR has to merge first."
on_main=$(git show origin/main:"$EAS_JSON" 2>/dev/null | jq -r '.submit.production.ios.ascAppId // empty' || true)
if [[ -n "$on_main" ]]; then
  you "nothing. main has everything."
  ok "main has the Expo project and the App Store Connect app"
else
  changed=$(git status --short -- "$APP_JSON" "$EAS_JSON")
  you "tell Claude the wizard is at the hand-back. Then:"
  [[ -n "$changed" ]] && step "Claude commits these to the deploy PR:" && printf '%s\n' "$changed" | sed 's/^/        /'
  step "Merge the tooling PR, then the deploy PR."
  step "Re-run this wizard. It skips to the first release."
  finish
  exit 0
fi
printf '\n'; pause

# ── 14. First TestFlight build ─────────────────────────────────────────────
stage "First TestFlight build"
what "runs the Release workflow on main. With no build yet, it builds the app"
say  "                and submits it to TestFlight. Expect up to an hour: the free plan's"
say  "                queue, then about 20 minutes of building, then Apple's processing."
if [[ -n "$(gh release list --repo "$REPO" --limit 1 --json tagName -q '.[].tagName')" ]]; then
  you "nothing."
  ok "A release has already run: $(gh release list --repo "$REPO" --limit 1 --json tagName -q '.[].tagName')"
else
  you "say yes to start it. You can close this and watch it in GitHub Actions instead."
  if confirm "Run the Release workflow now?"; then
    gh workflow run release.yml --repo "$REPO" --ref main
    sleep 5
    run_id=$(gh run list --repo "$REPO" --workflow release.yml --limit 1 --json databaseId -q '.[0].databaseId')
    gh run watch "$run_id" --repo "$REPO" --exit-status || warn "The release failed. Open it with: gh run view $run_id --repo $REPO --log-failed"
  else
    SKIPPED+=("Run the first release: gh workflow run release.yml --ref main")
  fi
fi
say "Once Apple has processed the build (App Store Connect emails you):"
step "App Store Connect → Users and Access → + → invite your partner. Any role works for"
say  "           TestFlight; Customer Support sees the least."
step "Your app → TestFlight → Internal Testing → + → a group called Household. Add"
say  "           yourself and your partner, and turn on automatic distribution."
step "On each iPhone, install TestFlight from the App Store and accept the email invite."
open_url "https://appstoreconnect.apple.com/access/users"
printf '\n'; pause "Press Enter to finish."

finish
note "From now on: merge to deploy the API, run Release (GitHub → Actions) to update the phones."
printf '\n'
}

run_wizard "$@"; exit
